package dev.nexflow.order; import jakarta.validation.Valid; import org.springframework.http.HttpStatus; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController {private final OrderService service;public OrderController(OrderService s){service=s;}@GetMapping public List<OrderDtos.View> list(){return service.list();}@PostMapping @ResponseStatus(HttpStatus.CREATED) public OrderDtos.View create(@Valid @RequestBody OrderDtos.CreateRequest r,Authentication a){return service.create(r,a.getName());}@PatchMapping("/{id}/status") public OrderDtos.View status(@PathVariable UUID id,@Valid @RequestBody OrderDtos.StatusRequest r,Authentication a){return service.updateStatus(id,r.status(),a.getName());}}
